 { plugin as default };\n","import React from 'react';\r\nimport { Pie } from 'react-chartjs-2';\r\nimport {\r\n    Chart as ChartJS,\r\n    ArcElement,\r\n    Tooltip,\r\n    Legend,\r\n} from 'chart.js';\r\nimport ChartDataLabels from 'chartjs-plugin-datalabels';\r\n\r\nChartJS.register(ArcElement, Tooltip, Legend, ChartDataLabels);\r\n\r\nfunction CashFlowPieChart({ transactions }) {\r\n    const totalIn = transactions.reduce((sum, t) => sum + (t.cashIn || 0), 0);\r\n    const totalOut = transactions.reduce((sum, t) => sum + (t.cashOut || 0), 0);\r\n    const hasData = totalIn > 0 || totalOut > 0;\r\n\r\n    const data = hasData\r\n        ? {\r\n            labels: ['Cash In', 'Cash Out'],\r\n            datasets: [\r\n                {\r\n                    data: [totalIn, totalOut],\r\n                    backgroundColor: ['#00c49f', '#ff8042'],\r\n                    borderWidth: 1,\r\n                }\r\n            ]\r\n        }\r\n        : {\r\n            labels: ['No Data'],\r\n            datasets: [\r\n                {\r\n                    data: [1],\r\n                    backgroundColor: ['#999'],\r\n                    borderWidth: 1\r\n                }\r\n            ]\r\n        };\r\n\r\n    const options = {\r\n        responsive: true,\r\n        plugins: {\r\n            legend: {\r\n                display: hasData,\r\n                position: 'bottom',\r\n                labels: {\r\n                    color: '#fff'\r\n                }\r\n            },\r\n            tooltip: {\r\n                enabled: hasData\r\n            },\r\n            datalabels: {\r\n                display: hasData,\r\n                color: '#fff',\r\n                font: {\r\n                    weight: 'bold',\r\n                    size: 12\r\n                },\r\n                formatter: (value, context) => {\r\n                    if (!hasData) return '';\r\n                    const total = totalIn + totalOut;\r\n                    const percent = ((value / total) * 100).toFixed(1);\r\n                    return `₹${value}\\n(${percent}%)`;\r\n                }\r\n            }\r\n        }\r\n    };\r\n\r\n    return (\r\n        <div style={{ maxWidth: 400, margin: '0 auto', position: 'relative' }}>\r\n            <Pie data={data} options={options} />\r\n            {!hasData && (\r\n                <div\r\n                    style={{\r\n                        position: 'absolute',\r\n                        top: '45%',\r\n                        left: '50%',\r\n                        transform: 'translate(-50%, -50%)',\r\n                        color: '#ccc',\r\n                        fontWeight: 'bold'\r\n                    }}\r\n                >\r\n                    No Cash Flow Data\r\n                </div>\r\n            )}\r\n        </div>\r\n    );\r\n}\r\n\r\nexport default CashFlowPieChart;\r\n","import * as XLSX from 'xlsx-js-style';\r\nimport { saveAs } from 'file-saver';\r\n\r\nexport function exportToExcel(data, fromDate, toDate) {\r\n    const wb = XLSX.utils.book_new();\r\n    const wsData = [];\r\n\r\n    // App title\r\n    wsData.push(['Cash Book App']);\r\n    wsData.push([]); // empty row\r\n\r\n    // Header\r\n    wsData.push(['Date', 'Description', 'Cash In', 'Cash Out']);\r\n\r\n    let totalIn = 0;\r\n    let totalOut = 0;\r\n\r\n    data.forEach((t) => {\r\n        const cashIn = parseFloat(t.cashIn) || 0;\r\n        const cashOut = parseFloat(t.cashOut) || 0;\r\n        wsData.push([\r\n            formatDate(new Date(t.date)),\r\n            t.description,\r\n            cashIn ? cashIn : '',\r\n            cashOut ? cashOut : ''\r\n        ]);\r\n        totalIn += cashIn;\r\n        totalOut += cashOut;\r\n    });\r\n\r\n    // Add total row with merged columns C & D\r\n    const totalRowIndex = wsData.length + 1;\r\n    debugger\r\n    wsData.push(['Total', '', `Balance: ${totalIn - totalOut}`]);\r\n\r\n    // Generate sheet\r\n    const ws = XLSX.utils.aoa_to_sheet(wsData);\r\n\r\n    // Column widths\r\n    const colWidths = wsData[2].map((_, colIdx) => {\r\n        const maxLen = Math.max(...wsData.map(r => (r[colIdx] ? r[colIdx].toString().length : 0)));\r\n        return { wch: maxLen + 5 };\r\n    });\r\n    ws['!cols'] = colWidths;\r\n\r\n    // Merge app title across all columns\r\n    ws['!merges'] = [\r\n        { s: { r: 0, c: 0 }, e: { r: 0, c: 3 } }, // A1 to D1\r\n        { s: { r: totalRowIndex - 1, c: 2 }, e: { r: totalRowIndex - 1, c: 3 } } // Merge C & D in total row\r\n    ];\r\n\r\n    // Style app title\r\n    ws['A1'].s = {\r\n        font: { bold: true, sz: 14 },\r\n        alignment: { horizontal: 'center' },\r\n        fill: { fgColor: { rgb: '12aaf1' } }\r\n    };\r\n\r\n    // Style headers\r\n    ['A3', 'B3', 'C3', 'D3'].forEach((cell) => {\r\n        ws[cell].s = {\r\n            font: { bold: true },\r\n            fill: { fgColor: { rgb: '12aaf1' } },\r\n            alignment: { horizontal: 'center', vertical: 'center' },\r\n            border: borderStyle()\r\n        };\r\n    });\r\n\r\n    // Style all data and total cells\r\n    Object.keys(ws).forEach((cell) => {\r\n        if (!cell.startsWith('!') && !ws[cell].s) {\r\n            ws[cell].s = {\r\n                alignment: { horizontal: 'center', vertical: 'center' },\r\n                border: borderStyle()\r\n            };\r\n        }\r\n    });\r\n\r\n    // Style total row (bold + border)\r\n    const totalCell = `C${totalRowIndex}`;\r\n    if (ws[totalCell]) {\r\n        ws[totalCell].s = {\r\n            font: { bold: true },\r\n            alignment: { horizontal: 'center' },\r\n            fill: { fgColor: { rgb: 'FFFFCC' } },\r\n            border: borderStyle()\r\n        };\r\n    }\r\n\r\n    // Optional: style \"Total\" label cell\r\n    if (ws[`A${totalRowIndex}`]) {\r\n        ws[`A${totalRowIndex}`].s = {\r\n            font: { bold: true },\r\n            alignment: { horizontal: 'center' },\r\n            border: borderStyle()\r\n        };\r\n    }\r\n\r\n    // Append and export\r\n    XLSX.utils.book_append_sheet(wb, ws, 'Report');\r\n    const filename = fromDate && toDate\r\n        ? `Cashbook_${fromDate}_to_${toDate}.xlsx`\r\n        : `Cashbook_${new Date().getFullYear()}-${new Date().getMonth() + 1}.xlsx`;\r\n\r\n    const wbout = XLSX.write(wb, { bookType: 'xlsx', type: 'binary' });\r\n    const buf = new ArrayBuffer(wbout.length);\r\n    const view = new Uint8Array(buf);\r\n    for (let i = 0; i !== wbout.length; ++i) view[i] = wbout.charCodeAt(i) & 0xFF;\r\n\r\n    saveAs(new Blob([buf], { type: 'application/octet-stream' }), filename);\r\n}\r\n\r\n// Utility to apply border style\r\nfunction borderStyle() {\r\n    return {\r\n        top: { style: 'thin', color: { rgb: '000000' } },\r\n        bottom: { style: 'thin', color: { rgb: '000000' } },\r\n        left: { style: 'thin', color: { rgb: '000000' } },\r\n        right: { style: 'thin', color: { rgb: '000000' } }\r\n    };\r\n}\r\n\r\n// Utility to format date\r\nfunction formatDate(date) {\r\n    const dd = String(date.getDate()).padStart(2, '0');\r\n    const mm = String(date.getMonth() + 1).padStart(2, '0');\r\n    const yyyy = date.getFullYear();\r\n    const hh = String(date.getHours()).padStart(2, '0');\r\n    const min = String(date.getMinutes()).padStart(2, '0');\r\n    return `${dd}-${mm}-${yyyy} ${hh}:${min}`;\r\n}\r\n","// component/HeaderSection.js\r\nimport { useEffect } from 'react';\r\nimport CashFlowPieChart from './CashFlowPieChart';\r\n\r\n\r\nimport $ from 'jquery';\r\nimport 'jquery-ui/ui/widgets/datepicker';\r\nimport 'jquery-ui-dist/jquery-ui.css';\r\nimport { exportToExcel } from '../utils/exportExcel';\r\n\r\nfunction HeaderSection({\r\n    transactions,\r\n    fromDate,\r\n    toDate,\r\n    setFromDate,\r\n    setToDate\r\n}) {\r\n    useEffect(() => {\r\n        const parseDate = (str) => {\r\n            const [dd, mm, yyyy] = str.split('-');\r\n            return new Date(`${yyyy}-${mm}-${dd}`);\r\n        };\r\n\r\n        // Initialize From Datepicker\r\n        $('#fromDateInput').datepicker({\r\n            dateFormat: 'dd-mm-yy',\r\n            changeMonth: true,\r\n            changeYear: true,\r\n            showAnim: 'fadeIn',\r\n            onSelect: function (dateText) {\r\n                setFromDate(dateText);\r\n\r\n                const minToDate = parseDate(dateText);\r\n\r\n                // Reset To Date if it's before the new From Date\r\n                if (toDate && parseDate(toDate) < minToDate) {\r\n                    setToDate('');\r\n                    $('#toDateInput').val('');\r\n                }\r\n\r\n                // Reinitialize To Datepicker with updated minDate\r\n                $('#toDateInput').datepicker('option', 'minDate', minToDate);\r\n            }\r\n        });\r\n\r\n        // Initialize To Datepicker\r\n        $('#toDateInput').datepicker({\r\n            dateFormat: 'dd-mm-yy',\r\n            changeMonth: true,\r\n            changeYear: true,\r\n            showAnim: 'fadeIn',\r\n            onSelect: function (dateText) {\r\n                setToDate(dateText);\r\n            }\r\n        });\r\n\r\n        // If fromDate already selected, set minDate initially\r\n        if (fromDate) {\r\n            const minToDate = parseDate(fromDate);\r\n            $('#toDateInput').datepicker('option', 'minDate', minToDate);\r\n        }\r\n    }, [fromDate, toDate, setFromDate, setToDate]);\r\n\r\n\r\n    return (<>\r\n        <div id='pieChartDiv' >\r\n            <CashFlowPieChart transactions={transactions} />\r\n        </div>\r\n\r\n        <div className=\"excel-export\">\r\n            <label>📊 Download Reports in Excel:</label>\r\n            <div className=\"date-inputs\">\r\n                <div className=\"date-input-group\">\r\n                    <label htmlFor=\"fromDateInput\">From Date</label>\r\n                    <input\r\n                        type=\"text\"\r\n                        id=\"fromDateInput\"\r\n                        placeholder=\"DD-MM-YYYY\"\r\n                        value={fromDate}\r\n                        readOnly\r\n                        onChange={(e) => setFromDate(e.target.value)}\r\n                    />\r\n                </div>\r\n                <div className=\"date-input-group\">\r\n                    <label htmlFor=\"toDateInput\">To Date</label>\r\n                    <input\r\n                        type=\"text\"\r\n                        id=\"toDateInput\"\r\n                        placeholder=\"DD-MM-YYYY\"\r\n                        value={toDate}\r\n                        readOnly\r\n                        onChange={(e) => setToDate(e.target.value)}\r\n                    />\r\n                </div>\r\n                <div className=\"download-button-wrapper\">\r\n                    <button onClick={() => exportToExcel(transactions, fromDate, toDate, setFromDate, setToDate)}>\r\n                        📥 Download\r\n                    </button>\r\n                    <button\r\n                        style={{ marginLeft: '0.5rem', backgroundColor: '#dc3545' }}\r\n                        onClick={() => {\r\n                            setFromDate('');\r\n                            setToDate('');\r\n                            $('#fromDateInput').datepicker('setDate', null);\r\n                            $('#toDateInput').datepicker('setDate', null);\r\n                            $('#toDateInput').datepicker('option', 'minDate', null);\r\n                        }}\r\n                    >\r\n                        ❌ Clear\r\n                    </button>\r\n                </div>\r\n            </div>\r\n        </div>\r\n    </>\r\n    );\r\n}\r\n\r\nexport default HeaderSection;\r\n","// component/TransactionSection.js\r\nimport React from 'react';\r\n\r\nfunction TransactionSection({\r\n    transactions,\r\n    formType,\r\n    description,\r\n    cashIn,\r\n    cashOut,\r\n    editId,\r\n    setFormType,\r\n    setDescription,\r\n    setCashIn,\r\n    setCashOut,\r\n    startEdit,\r\n    cancelEdit,\r\n    deleteTransaction,\r\n    submitTransaction\r\n}) {\r\n    const [activeTab, setActiveTab] = React.useState('Daily');\r\n    const [menuOpen, setMenuOpen] = React.useState(false);\r\n\r\n    const now = new Date();\r\n\r\n    function formatDate(date) {\r\n        const dd = String(date.getDate()).padStart(2, '0');\r\n        const mm = String(date.getMonth() + 1).padStart(2, '0');\r\n        const yyyy = date.getFullYear();\r\n        const hh = String(date.getHours()).padStart(2, '0');\r\n        const min = String(date.getMinutes()).padStart(2, '0');\r\n        return `${dd}-${mm}-${yyyy} ${hh}:${min}`;\r\n    }\r\n\r\n    function getWeekNumber(d) {\r\n        const date = new Date(Date.UTC(d.getFullYear(), d.getMonth(), d.getDate()));\r\n        const dayNum = date.getUTCDay() || 7;\r\n        date.setUTCDate(date.getUTCDate() + 4 - dayNum);\r\n        const yearStart = new Date(Date.UTC(date.getUTCFullYear(), 0, 1));\r\n        return Math.ceil(((date - yearStart) / 86400000 + 1) / 7);\r\n    }\r\n\r\n    const filteredTransactions = transactions.filter((t) => {\r\n        const date = new Date(t.date);\r\n        const currentYear = now.getFullYear();\r\n        const currentMonth = now.getMonth();\r\n        const currentWeek = getWeekNumber(now);\r\n        const txWeek = getWeekNumber(date);\r\n\r\n        switch (activeTab) {\r\n            case 'Daily':\r\n                return date.toDateString() === now.toDateString();\r\n            case 'Weekly':\r\n                return date.getFullYear() === currentYear && txWeek === currentWeek;\r\n            case 'Monthly':\r\n                return date.getFullYear() === currentYear && date.getMonth() === currentMonth;\r\n            default:\r\n                return true;\r\n        }\r\n    });\r\n\r\n    const totalCashIn = filteredTransactions.reduce((sum, t) => sum + t.cashIn, 0);\r\n    const totalCashOut = filteredTransactions.reduce((sum, t) => sum + t.cashOut, 0);\r\n    const balance = totalCashIn - totalCashOut;\r\n\r\n    return (\r\n        <section className=\"cash-book\">\r\n            <div className=\"tabs-container\">\r\n                <div className=\"menu-toggle\" onClick={() => setMenuOpen(!menuOpen)}>\r\n                    ☰ Menu\r\n                </div>\r\n                <div className={`tabs ${menuOpen ? 'show' : 'hide'}`}>\r\n                    {['Daily', 'Weekly', 'Monthly', 'All'].map((tab) => (\r\n                        <button\r\n                            key={tab}\r\n                            className={activeTab === tab ? 'active' : ''}\r\n                            onClick={() => {\r\n                                setActiveTab(tab);\r\n                                setMenuOpen(false);\r\n                            }}\r\n                        >\r\n                            {tab}\r\n                        </button>\r\n                    ))}\r\n                </div>\r\n            </div>\r\n\r\n            <div className=\"transaction-type-buttons\">\r\n                <button\r\n                    className={formType === 'cashIn' ? 'active' : ''}\r\n                    onClick={() => setFormType('cashIn')}\r\n                >\r\n                    💰 Cash In\r\n                </button>\r\n                <button\r\n                    className={formType === 'cashOut' ? 'active' : ''}\r\n                    onClick={() => setFormType('cashOut')}\r\n                >\r\n                    💸 Cash Out\r\n                </button>\r\n            </div>\r\n\r\n            {formType && (\r\n                <div className=\"add-transaction-form\">\r\n                    <input\r\n                        type=\"text\"\r\n                        placeholder=\"Description\"\r\n                        value={description}\r\n                        onChange={(e) => setDescription(e.target.value)}\r\n                    />\r\n                    {formType === 'cashIn' && (\r\n                        <input\r\n                            type=\"number\"\r\n                            placeholder=\"Cash In\"\r\n                            value={cashIn}\r\n                            onChange={(e) => setCashIn(e.target.value)}\r\n                        />\r\n                    )}\r\n                    {formType === 'cashOut' && (\r\n                        <input\r\n                            type=\"number\"\r\n                            placeholder=\"Cash Out\"\r\n                            value={cashOut}\r\n                            onChange={(e) => setCashOut(e.target.value)}\r\n                        />\r\n                    )}\r\n                    <button onClick={submitTransaction}>\r\n                        {editId ? 'Update' : 'Add'} {formType === 'cashIn' ? 'Cash In' : 'Cash Out'}\r\n                    </button>\r\n                    {editId && <button onClick={cancelEdit}>Cancel</button>}\r\n                </div>\r\n            )}\r\n\r\n            <div className=\"transactions-table\">\r\n                <table>\r\n                    <thead>\r\n                        <tr>\r\n                            <th>Date</th>\r\n                            <th>Cash In</th>\r\n                            <th>Cash Out</th>\r\n                        </tr>\r\n                    </thead>\r\n                    <tbody>\r\n                        {filteredTransactions.map((transaction) => (\r\n                            <tr key={transaction.id}>\r\n                                <td>\r\n                                    <div className=\"date\">{formatDate(new Date(transaction.date))}</div>\r\n                                    <div className=\"description\">{transaction.description}</div>\r\n                                    <div className=\"actions\">\r\n                                        <button\r\n                                            className=\"edit-btn\"\r\n                                            onClick={() => startEdit(transaction)}\r\n                                        >\r\n                                            ✏️ Edit\r\n                                        </button>\r\n                                        <button\r\n                                            className=\"delete-btn\"\r\n                                            onClick={() => {\r\n                                                if (editId === transaction.id) cancelEdit();\r\n                                                deleteTransaction(transaction.id);\r\n                                            }}\r\n                                        >\r\n                                            🗑️ Delete\r\n                                        </button>\r\n                                    </div>\r\n                                </td>\r\n                                <td className=\"cash-in\">\r\n                                    {transaction.cashIn > 0 ? `₹${transaction.cashIn.toLocaleString()}` : ''}\r\n                                </td>\r\n                                <td className=\"cash-out\">\r\n                                    {transaction.cashOut > 0 ? `₹${transaction.cashOut.toLocaleString()}` : ''}\r\n                                </td>\r\n                            </tr>\r\n                        ))}\r\n                    </tbody>\r\n                </table>\r\n            </div>\r\n\r\n            <div className=\"totals\">\r\n                <div>Total Cash In: ₹{totalCashIn.toLocaleString()}</div>\r\n                <div>Total Cash Out: ₹{totalCashOut.toLocaleString()}</div>\r\n                <div className={`balance ${balance < 0 ? 'negative' : ''}`}>\r\n                    Balance: ₹{Math.abs(balance).toLocaleString()}\r\n                </div>\r\n            </div>\r\n        </section>\r\n    );\r\n}\r\n\r\nexport default TransactionSection;\r\n","// component/Navbar.js\r\nimport React from 'react';\r\nimport './css/Navbar.css'; // optional CSS\r\n\r\nfunction Navbar() {\r\n    return (\r\n        <nav className=\"navbar\">\r\n            <div className=\"navbar-brand\">💼 My Cash Book</div>\r\n        </nav>\r\n    );\r\n}\r\n\r\nexport default Navbar;\r\n","import React from 'react';\nimport './App.css';\nimport './utils/ExcelSheet.css';\nimport useTransactions from './component/TransactionManager';\n// ✅ Working\nimport * as XLSX from 'xlsx-js-style';\n\n\nimport { saveAs } from 'file-saver';\nimport $ from 'jquery';\nimport 'jquery-ui/ui/widgets/datepicker';\nimport 'jquery-ui-dist/jquery-ui.css';\n\nimport HeaderSection from './component/HeaderSection';\nimport TransactionSection from './component/TransactionSection';\nimport Navbar from './component/Navbar';\n\nfunction App() {\n  const {\n    transactions,\n    formType,\n    description,\n    cashIn,\n    cashOut,\n    editId,\n    setFormType,\n    setDescription,\n    setCashIn,\n    setCashOut,\n    startEdit,\n    cancelEdit,\n    deleteTransaction,\n    submitTransaction\n  } = useTransactions();\n\n  const [fromDate, setFromDate] = React.useState('');\n  const [toDate, setToDate] = React.useState('');\n  // eslint-disable-next-line \n  React.useEffect(() => {\n    // Utility to parse dd-mm-yyyy to Date object\n    const parseDate = (str) => {\n      const [dd, mm, yyyy] = str.split('-');\n      return new Date(`${yyyy}-${mm}-${dd}`);\n    };\n\n    // FROM Date Picker\n    $('#fromDateInput').datepicker({\n      dateFormat: 'dd-mm-yy',\n      changeMonth: true,\n      changeYear: true,\n      showAnim: 'fadeIn',\n      onSelect: function (selectedDate) {\n        setFromDate(selectedDate);\n\n        const minToDate = parseDate(selectedDate);\n\n        // Destroy and recreate TO datepicker with updated minDate\n        $('#toDateInput').datepicker('destroy');\n        $('#toDateInput').datepicker({\n          dateFormat: 'dd-mm-yy',\n          changeMonth: true,\n          changeYear: true,\n          showAnim: 'fadeIn',\n          minDate: minToDate,\n          onSelect: function (toDateText) {\n            setToDate(toDateText);\n          }\n        });\n\n        // If currently selected ToDate is before the new FromDate, clear it\n        if (toDate && parseDate(toDate) < minToDate) {\n          setToDate('');\n          $('#toDateInput').val('');\n        }\n      }\n    });\n\n    // TO Date Picker Initial (no restriction)\n    $('#toDateInput').datepicker({\n      dateFormat: 'dd-mm-yy',\n      changeMonth: true,\n      changeYear: true,\n      showAnim: 'fadeIn',\n      onSelect: function (dateText) {\n        setToDate(dateText);\n      }\n    });\n  }, []);\n\n\n\n\n  function formatDate(date) {\n    const dd = String(date.getDate()).padStart(2, '0');\n    const mm = String(date.getMonth() + 1).padStart(2, '0');\n    const yyyy = date.getFullYear();\n    const hh = String(date.getHours()).padStart(2, '0');\n    const min = String(date.getMinutes()).padStart(2, '0');\n    return `${dd}-${mm}-${yyyy} ${hh}:${min}`;\n  }\n\n  function downloadExcel(from, to) {\n    let exportData = [];\n\n    const parseDate = (str) => {\n      const [dd, mm, yyyy] = str.split('-');\n      return new Date(`${yyyy}-${mm}-${dd}`);\n    };\n\n    if (from && to) {\n      const fromTime = parseDate(from).setHours(0, 0, 0, 0);\n      const toTime = parseDate(to).setHours(23, 59, 59, 999);\n\n      exportData = transactions.filter((t) => {\n        const txTime = new Date(t.date).getTime();\n        return txTime >= fromTime && txTime <= toTime;\n      });\n    } else {\n      const now = new Date();\n      const currentYear = now.getFullYear();\n      const currentMonth = now.getMonth();\n\n      exportData = transactions.filter((t) => {\n        const date = new Date(t.date);\n        return date.getFullYear() === currentYear && date.getMonth() === currentMonth;\n      });\n    }\n\n    const data = exportData.map((t) => ({\n      Date: formatDate(new Date(t.date)),\n      Description: t.description,\n      'Cash In': t.cashIn || '',\n      'Cash Out': t.cashOut || '',\n    }));\n\n    const worksheet = XLSX.utils.json_to_sheet(data);\n    const workbook = XLSX.utils.book_new();\n    XLSX.utils.book_append_sheet(workbook, worksheet, 'Export');\n\n    const now = new Date();\n    const fileName = from && to\n      ? `Cashbook_${from}_to_${to}.xlsx`\n      : `Cashbook_${now.getFullYear()}-${now.getMonth() + 1}.xlsx`;\n\n    const excelBuffer = XLSX.write(workbook, { bookType: 'xlsx', type: 'array' });\n    const fileData = new Blob([excelBuffer], { type: 'application/octet-stream' });\n    saveAs(fileData, fileName);\n\n    setFromDate('');\n    setToDate('');\n  }\n\n  return (\n    <div className=\"app dark-mode\">\n      <Navbar />\n      <header>\n        <HeaderSection\n          transactions={transactions}\n          fromDate={fromDate}\n          toDate={toDate}\n          setFromDate={setFromDate}\n          setToDate={setToDate}\n          downloadExcel={downloadExcel}\n        />\n      </header>\n\n      <main>\n        <TransactionSection\n          transactions={transactions}\n          formType={formType}\n          description={description}\n          cashIn={cashIn}\n          cashOut={cashOut}\n          editId={editId}\n          setFormType={setFormType}\n          setDescription={setDescription}\n          setCashIn={setCashIn}\n          setCashOut={setCashOut}\n          startEdit={startEdit}\n          cancelEdit={cancelEdit}\n          deleteTransaction={deleteTransaction}\n          submitTransaction={submitTransaction}\n        />\n      </main>\n    </div>\n  );\n}\n\nexport default App;\n","// TransactionManager.js\r\nimport { useState, useEffect } from 'react';\r\n\r\nexport default function useTransactions() {\r\n    const [transactions, setTransactions] = useState([]);\r\n    const [editId, setEditId] = useState(null);\r\n    const [formType, setFormType] = useState(null);\r\n    const [description, setDescription] = useState('');\r\n    const [cashIn, setCashIn] = useState('');\r\n    const [cashOut, setCashOut] = useState('');\r\n\r\n    useEffect(() => {\r\n        const saved = localStorage.getItem('transactions');\r\n        if (saved) setTransactions(JSON.parse(saved));\r\n    }, []);\r\n\r\n    useEffect(() => {\r\n        localStorage.setItem('transactions', JSON.stringify(transactions));\r\n    }, [transactions]);\r\n\r\n    const startEdit = (txn) => {\r\n        setFormType(txn.cashIn > 0 ? 'cashIn' : 'cashOut');\r\n        setDescription(txn.description);\r\n        setCashIn(txn.cashIn || '');\r\n        setCashOut(txn.cashOut || '');\r\n        setEditId(txn.id);\r\n    };\r\n\r\n    const cancelEdit = () => {\r\n        setFormType(null);\r\n        setDescription('');\r\n        setCashIn('');\r\n        setCashOut('');\r\n        setEditId(null);\r\n    };\r\n\r\n    const deleteTransaction = (id) => {\r\n        if (window.confirm('Delete this transaction?')) {\r\n            setTransactions(transactions.filter(t => t.id !== id));\r\n        }\r\n    };\r\n\r\n    const submitTransaction = () => {\r\n        const cashInValue = parseFloat(cashIn);\r\n        const cashOutValue = parseFloat(cashOut);\r\n        const now = new Date();\r\n\r\n        if (!description.trim()) {\r\n            alert('Please enter a description');\r\n            return;\r\n        }\r\n\r\n        if (\r\n            (formType === 'cashIn' && (isNaN(cashInValue) || cashInValue <= 0)) ||\r\n            (formType === 'cashOut' && (isNaN(cashOutValue) || cashOutValue <= 0))\r\n        ) {\r\n            alert('Please enter a valid amount');\r\n            return;\r\n        }\r\n\r\n        const newTxn = {\r\n            id: editId || Date.now(),\r\n            date: editId ? transactions.find(t => t.id === editId).date : now,\r\n            description: description.trim(),\r\n            cashIn: formType === 'cashIn' ? cashInValue : 0,\r\n            cashOut: formType === 'cashOut' ? cashOutValue : 0,\r\n        };\r\n\r\n        if (editId) {\r\n            setTransactions(transactions.map(t => t.id === editId ? newTxn : t));\r\n        } else {\r\n            setTransactions([newTxn, ...transactions]);\r\n        }\r\n\r\n        cancelEdit();\r\n    };\r\n\r\n    return {\r\n        transactions,\r\n        formType,\r\n        description,\r\n        cashIn,\r\n        cashOut,\r\n        editId,\r\n        setFormType,\r\n        setDescription,\r\n        setCashIn,\r\n        setCashOut,\r\n        startEdit,\r\n        cancelEdit,\r\n        deleteTransaction,\r\n        submitTransaction\r\n    };\r\n}\r\n","const reportWebVitals = onPerfEntry => {\n  if (onPerfEntry && onPerfEntry instanceof Function) {\n    import('web-vitals').then(({ getCLS, getFID, getFCP, getLCP, getTTFB }) => {\n      getCLS(onPerfEntry);\n      getFID(onPerfEntry);\n      getFCP(onPerfEntry);\n      getLCP(onPerfEntry);\n      getTTFB(onPerfEntry);\n    });\n  }\n};\n\nexport default reportWebVitals;\n","// CRA default service worker registration helper\r\nconst isLocalhost = Boolean(\r\n    window.location.hostname === 'localhost' ||\r\n    window.location.hostname === '[::1]' ||\r\n    window.location.hostname.match(\r\n        /^127(?:\\.(?:25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)){3}$/\r\n    )\r\n);\r\n\r\nexport function register(config) {\r\n    if (process.env.NODE_ENV === 'production' && 'serviceWorker' in navigator) {\r\n        const publicUrl = new URL(process.env.PUBLIC_URL, window.location.href);\r\n        if (publicUrl.origin !== window.location.origin) return;\r\n\r\n        window.addEventListener('load', () => {\r\n            const swUrl = `${process.env.PUBLIC_URL}/service-worker.js`;\r\n\r\n            if (isLocalhost) {\r\n                checkValidServiceWorker(swUrl, config);\r\n                navigator.serviceWorker.ready.then(() => {\r\n                    console.log('PWA: This web app is being served cache-first by a service worker.');\r\n                });\r\n            } else {\r\n                registerValidSW(swUrl, config);\r\n            }\r\n        });\r\n    }\r\n}\r\n\r\nfunction registerValidSW(swUrl, config) {\r\n    navigator.serviceWorker\r\n        .register(swUrl)\r\n        .then(registration => {\r\n            registration.onupdatefound = () => {\r\n                const installingWorker = registration.installing;\r\n                if (!installingWorker) return;\r\n\r\n                installingWorker.onstatechange = () => {\r\n                    if (installingWorker.state === 'installed') {\r\n                        if (navigator.serviceWorker.controller) {\r\n                            console.log('PWA: New content is available; please refresh.');\r\n                            if (config?.onUpdate) config.onUpdate(registration);\r\n                        } else {\r\n                            console.log('PWA: Content cached for offline use.');\r\n                            if (config?.onSuccess) config.onSuccess(registration);\r\n                        }\r\n                    }\r\n                };\r\n            };\r\n        })\r\n        .catch(error => {\r\n            console.error('PWA: Error during service worker registration:', error);\r\n        });\r\n}\r\n\r\nfunction checkValidServiceWorker(swUrl, config) {\r\n    fetch(swUrl, { headers: { 'Service-Worker': 'script' } })\r\n        .then(response => {\r\n            const contentType = response.headers.get('content-type');\r\n            if (\r\n                response.status === 404 ||\r\n                (contentType && !contentType.includes('javascript'))\r\n            ) {\r\n                navigator.serviceWorker.ready.then(registration => {\r\n                    registration.unregister().then(() => window.location.reload());\r\n                });\r\n            } else {\r\n                registerValidSW(swUrl, config);\r\n            }\r\n        })\r\n        .catch(() => {\r\n            console.log('PWA: No internet connection. App is running in offline mode.');\r\n        });\r\n}\r\n\r\nexport function unregister() {\r\n    if ('serviceWorker' in navigator) {\r\n        navigator.serviceWorker.ready.then(registration => registration.unregister());\r\n    }\r\n}\r\n","import React from 'react';\nimport ReactDOM from 'react-dom/client';\nimport './index.css';\nimport App from './App';\nimport reportWebVitals from './reportWebVitals';\nimport * as serviceWorkerRegistration from './serviceWorkerRegistration'; // ✅ Add this\n\nconst root = ReactDOM.createRoot(document.getElementById('root'));\nroot.render(\n  <React.StrictMode>\n    <App />\n  </React.StrictMode>\n);\n\n// ✅ Register service worker\nserviceWorkerRegistration.register();\n\nreportWebVitals();\n"],"names":["Scheduler","require","React","ReactDOM","formatProdErrorMessage","code","url","arguments","length","encodeURIComponent","i","isValidContainer","node","nodeType","getNearestMountedFiber","fiber","nearestMounted","alternate","return","flags","tag","getSuspenseInstanceFromFiber","suspenseState","memoizedState","dehydrated","assertIsMounted","Error","findCurrentHostFiberImpl","child","sibling","assign","Object","REACT_LEGACY_ELEMENT_TYPE","Symbol","for","REACT_ELEMENT_TYPE","REACT_PORTAL_TYPE","REACT_FRAGMENT_TYPE","REACT_STRICT_MODE_TYPE","REACT_PROFILER_TYPE","REACT_PROVIDER_TYPE","REACT_CONSUMER_TYPE","REACT_CONTEXT_TYPE","REACT_FORWARD_REF_TYPE","REACT_SUSPENSE_TYPE","REACT_SUSPENSE_LIST_TYPE","REACT_MEMO_TYPE","REACT_LAZY_TYPE","REACT_ACTIVITY_TYPE","REACT_MEMO_CACHE_SENTINEL","MAYBE_ITERATOR_SYMBOL","iterator","getIteratorFn","maybeIterable","REACT_CLIENT_REFERENCE","getComponentNameFromType","type","$$typeof","displayName","name","_context","innerType","render","_payload","_init","x","isArrayImpl","Array","isArray","ReactSharedInternals","__CLIENT_INTERNALS_DO_NOT_USE_OR_WARN_USERS_THEY_CANNOT_UPGR